def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]

    if not points:
        return out

    # Treat each 3-region independently; its bounding box gives the inward
    # direction for markers just outside the region.
    unseen = set(points)
    regions = []
    while unseen:
        start = unseen.pop()
        comp = [start]
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q = (r+dr, c+dc)
                if q in unseen:
                    unseen.remove(q)
                    comp.append(q)
                    stack.append(q)
        regions.append(comp)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            region = min(regions, key=lambda comp:
                         min(abs(r-y)+abs(c-x) for y,x in comp))
            dist = min(abs(r-y)+abs(c-x) for y,x in region)
            if dist <= 1:
                cr, cc = r, c
            elif dist <= 4:
                # Project the marker to the closest point on the shape and
                # move one step inward.
                y, x = min(region, key=lambda p: abs(r-p[0])+abs(c-p[1]))
                rmid = sum(y0 for y0, _ in region) / len(region)
                cmid = sum(x0 for _, x0 in region) / len(region)
                cr = y + ((1 if rmid > y else -1) if rmid != y else 0)
                cc = x + ((1 if cmid > x else -1) if cmid != x else 0)
            else:
                continue

            for rr in range(cr-1, cr+2):
                for cc2 in range(cc-1, cc+2):
                    if 0 <= rr < h and 0 <= cc2 < w and grid[rr][cc2] != 2:
                        out[rr][cc2] = 1
    return out
